const refreshMessageCurrentVersion = `-- name: RefreshMessageCurrentVersion :exec
update messages m
set body = v.body, edited_at = v.occurred_at
from (
    select c.body, c.occurred_at from message_changes c
    where c.message_id = $1 and c.kind = 'edit'
    order by c.occurred_at desc, c.id desc
    limit 1
) v
where m.id = $1
`

// The current content of an edited message is its newest recorded edit, by
// the time of the provider (then the order received): a late edit is kept as
// a version but never undoes a newer one, whatever text either has.
func (q *Queries) RefreshMessageCurrentVersion(ctx context.Context, id int64) error {
	_, err := q.db.Exec(ctx, refreshMessageCurrentVersion, id)
	return err
}

const retryMessage = `-- name: RetryMessage :one
update messages
set status = 'pending', failure_reason = null
where id = $1 and status = 'failed' and deleted_at is null
returning id, ticket_id, sector_id, contact_id, direction, origin, author_id, type, body, media_id, external_message_id, client_request_id, status, failure_reason, sent_at, created_at, updated_at, quoted_external_message_id, quoted_message_id, quoted_type, quoted_body, edited_at, deleted_at, deletion_scope, deletion_origin
`

// Only a failed message goes back to pending, so a double click retries once.
// A deleted message is never sent again.
func (q *Queries) RetryMessage(ctx context.Context, id int64) (Message, error) {
	row := q.db.QueryRow(ctx, retryMessage, id)
	var i Message
	err := row.Scan(
		&i.ID,
		&i.TicketID,
		&i.SectorID,
		&i.ContactID,
		&i.Direction,
		&i.Origin,
		&i.AuthorID,
		&i.Type,
		&i.Body,
		&i.MediaID,
		&i.ExternalMessageID,
		&i.ClientRequestID,
		&i.Status,
		&i.FailureReason,
		&i.SentAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.QuotedExternalMessageID,
		&i.QuotedMessageID,
		&i.QuotedType,
		&i.QuotedBody,
		&i.EditedAt,
		&i.DeletedAt,
		&i.DeletionScope,
		&i.DeletionOrigin,
	)
	return i, err
}
